<?php
require 'config.php';require 'includes/functions.php';
$_SESSION['cart']=$_SESSION['cart']??[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0);if($action==='remove'){unset($_SESSION['cart'][$id]);}elseif($action==='update'){foreach(($_POST['qty']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=max(0,min(99,(int)$qty));if($qty===0)unset($_SESSION['cart'][$pid]);else $_SESSION['cart'][$pid]=$qty;}}$_SESSION['flash']='Basket updated.';redirect('cart.php');}
$items=[];$total=0;foreach($_SESSION['cart'] as $id=>$qty){$s=$pdo->prepare('SELECT id,name,category,price,image,active FROM products WHERE id=?');$s->execute([(int)$id]);$p=$s->fetch();if(!$p||!(int)$p['active']){unset($_SESSION['cart'][$id]);continue;}$line=(float)$p['price']*(int)$qty;$p['quantity']=(int)$qty;$p['line_total']=$line;$items[]=$p;$total+=$line;}
$pageTitle='Your basket';require 'includes/header.php';?>
<div class="section-head"><div><div class="eyebrow">Your selection</div><h1>Shopping basket</h1></div><a class="btn btn-light" href="index.php">Continue shopping</a></div>
<?php if(!$items):?><div class="panel"><h2>Your basket is empty</h2><p class="muted">Choose a product to add it here. You can come back to your basket during this browser session.</p><a class="btn" href="index.php">Browse products</a></div><?php else:?><form method="post" class="panel"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><div class="table-wrap"><table><thead><tr><th>Product</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($items as $it):?><tr><td><a href="product.php?id=<?=$it['id']?>"><strong><?=e($it['name'])?></strong></a><br><span class="muted small"><?=e($it['category'])?></span></td><td><?=money($it['price'])?></td><td><input type="number" min="0" max="99" name="qty[<?=$it['id']?>]" value="<?=$it['quantity']?>" style="width:82px;padding:8px"></td><td><?=money($it['line_total'])?></td><td><button class="btn btn-light" type="submit" name="action" value="remove" formaction="cart.php" onclick="this.form.querySelector('[name=product_id]').value='<?=$it['id']?>'">Remove</button><input type="hidden" name="product_id" value="0"></td></tr><?php endforeach;?></tbody></table></div><div class="cart-total"><button class="btn btn-light">Update basket</button><h2>Total: <?=money($total)?></h2></div></form><div class="panel"><h2>Ready to pay?</h2><?php if(!is_logged_in()):?><p>Please log in or register before checkout. Your basket will remain in this browser session.</p><a class="btn" href="login.php">Log in to continue</a> <a class="btn btn-light" href="register.php">Register</a><?php else:?><a class="btn" href="checkout.php">Proceed to checkout</a><?php endif;?></div><?php endif;?><?php require 'includes/footer.php';?>